class Solution:
    def countSubarrays(self, nums: List[int], k: int, m: int) -> int:
        ans = 0
        c1, c0, c3 = {}, {}, {}
        d1 = d0 = 0
        l1 = l0 = G = 0
        for r, x in enumerate(nums):
            c1[x] = c1.get(x, 0) + 1
            if c1[x] == 1: d1 += 1
            while d1 > k:
                y = nums[l1]; c1[y] -= 1
                if c1[y] == 0: d1 -= 1
                l1 += 1
            c0[x] = c0.get(x, 0) + 1
            if c0[x] == 1: d0 += 1
            while d0 > k - 1:
                y = nums[l0]; c0[y] -= 1
                if c0[y] == 0: d0 -= 1
                l0 += 1
            c3[x] = c3.get(x, 0) + 1
            while G <= r:
                y = nums[G]
                if c3[y] - 1 == 0 or c3[y] - 1 >= m:
                    c3[y] -= 1; G += 1
                else:
                    break
            lo = max(l1, G); hi = min(l0 - 1, r)
            if hi >= lo: ans += hi - lo + 1
        return ans

