class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k, int m) {
        int n = nums.size(); long long ans = 0;
        unordered_map<int,int> c1, c0, c3;
        int d1 = 0, d0 = 0, l1 = 0, l0 = 0, G = 0;
        for (int r = 0; r < n; r++) {
            int x = nums[r];
            if (++c1[x] == 1) d1++;
            while (d1 > k) { int y = nums[l1++]; if (--c1[y] == 0) d1--; }
            if (++c0[x] == 1) d0++;
            while (d0 > k - 1) { int y = nums[l0++]; if (--c0[y] == 0) d0--; }
            ++c3[x];
            while (G <= r) {
                int y = nums[G];
                if (c3[y] - 1 == 0 || c3[y] - 1 >= m) { --c3[y]; G++; }
                else break;
            }
            long long lo = max(l1, G), hi = min(l0 - 1, r);
            if (hi >= lo) ans += hi - lo + 1;
        }
        return ans;
    }
};

