class Solution {
    public long countSubarrays(int[] nums, int k, int m) {
        int n = nums.length; long ans = 0;
        Map<Integer,Integer> c1 = new HashMap<>(), c0 = new HashMap<>(), c3 = new HashMap<>();
        int d1 = 0, d0 = 0, l1 = 0, l0 = 0, G = 0;
        for (int r = 0; r < n; r++) {
            int x = nums[r];
            d1 += c1.merge(x, 1, Integer::sum) == 1 ? 1 : 0;
            while (d1 > k) { int y = nums[l1++]; if (c1.merge(y, -1, Integer::sum) == 0) d1--; }
            d0 += c0.merge(x, 1, Integer::sum) == 1 ? 1 : 0;
            while (d0 > k - 1) { int y = nums[l0++]; if (c0.merge(y, -1, Integer::sum) == 0) d0--; }
            c3.merge(x, 1, Integer::sum);
            while (G <= r) {
                int y = nums[G];
                int c = c3.get(y) - 1;
                if (c == 0 || c >= m) { c3.put(y, c); G++; }
                else break;
            }
            long lo = Math.max(l1, G), hi = Math.min(l0 - 1, r);
            if (hi >= lo) ans += hi - lo + 1;
        }
        return ans;
    }
}

