var countSubarrays = function(nums, k, m) {
    let ans = 0;
    const c1 = new Map(), c0 = new Map(), c3 = new Map();
    let d1 = 0, d0 = 0, l1 = 0, l0 = 0, G = 0;
    const bump = (mp, x, dv) => {
        const v = (mp.get(x) || 0) + dv;
        if (v === 0) mp.delete(x); else mp.set(x, v);
        return v;
    };
    for (let r = 0; r < nums.length; r++) {
        const x = nums[r];
        if (bump(c1, x, 1) === 1) d1++;
        while (d1 > k) { if (bump(c1, nums[l1], -1) === 0) d1--; l1++; }
        if (bump(c0, x, 1) === 1) d0++;
        while (d0 > k - 1) { if (bump(c0, nums[l0], -1) === 0) d0--; l0++; }
        bump(c3, x, 1);
        while (G <= r) {
            const y = nums[G], c = (c3.get(y) || 0) - 1;
            if (c === 0 || c >= m) { bump(c3, y, -1); G++; }
            else break;
        }
        const lo = Math.max(l1, G), hi = Math.min(l0 - 1, r);
        if (hi >= lo) ans += hi - lo + 1;
    }
    return ans;
};
